/// <summary>
/// This is an extension class for VendParameters form and InvoiceMatching_UseTotalPriceMatching control.
/// </summary>
[ExtensionOf(formControlStr(VendParameters, InvoiceMatching_UseTotalPriceMatching))]
final class METVendParameters_UseTotalPriceMatching_Extension
{
}

Method.Source:
/// <summary>
/// Enable/disable the EnableMetcashMatchingLogic control.
/// </summary>
/// <returns>Boolean value</returns>
public boolean modified()
{
    boolean ret;

    ret = next modified();

    FormControl crtrl = this;
    FormRun formRun =  crtrl.formRun();
    METVendParameters metVendparm = formRun.dataSource(formDataSourceStr(VendParameters, METVendParameters)).cursor();
    VendParameters vendparm = this.formRun().dataSource(formDataSourceStr(VendParameters, VendParameters)).cursor();
    FormControl enableMetMatchCtrl = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_EnableMetcashMatchingLogic));
    FormControl taxinvTotToleranceCtrl = this.formRun().design(1).controlName(formControlStr(VendParameters, METVendParameters_TaxInvTotalsToleranceDollar));

    if (!vendparm.UseTotalPriceMatching)
    {
        enableMetMatchCtrl.enabled(true);

        if (metVendparm.EnableMetcashMatchingLogic)
        {
            taxinvTotToleranceCtrl.enabled(true);
        }
        else
        {
            taxinvTotToleranceCtrl.enabled(false);
        }
    }
    else
    {
        if (metVendparm.EnableMetcashMatchingLogic)
        {
            if (Box::okCancel('@MET:DisableMetcashMatchingLogic', DialogButton::Cancel) == DialogButton::Ok)
            {
                metVendparm.EnableMetcashMatchingLogic = NoYes::No;
                enableMetMatchCtrl.enabled(false);
                taxinvTotToleranceCtrl.enabled(false);
            }
            else
            {
                vendparm.UseTotalPriceMatching = NoYes::No;
            }
        }
        else
        {
            metVendparm.EnableMetcashMatchingLogic = NoYes::No;
            enableMetMatchCtrl.enabled(false);
            taxinvTotToleranceCtrl.enabled(false);
        }
    }

    return ret;
}
